NFA compileRegex(String postfix) {
  List<NFA> nfaStack = [];

  for (int i = 0; i < postfix.length; i++) {
    @pragma('vm:entry-point')
    final ch = postfix[i];
    switch (ch) {
      case '*':
        {
          NFA nfa1 = nfaStack.removeLast();
          State initial = State();
          State accept = State();
          initial.edge1 = nfa1.initial;
          initial.edge2 = accept;
          nfa1.accept.edge1 = nfa1.initial;
          nfa1.accept.edge2 = accept;
          nfaStack.add(NFA(initial, accept));
        }
        break;
      case '.':
        {
          NFA nfa2 = nfaStack.removeLast();
          NFA nfa1 = nfaStack.removeLast();
          nfa1.accept.edge1 = nfa2.initial;
          nfaStack.add(NFA(nfa1.initial, nfa2.accept));
        }
        break;
      case '|':
        {
          NFA nfa2 = nfaStack.removeLast();
          NFA nfa1 = nfaStack.removeLast();
          State initial = State();
          State accept = State();
          initial.edge1 = nfa1.initial;
          initial.edge2 = nfa2.initial;
          nfa1.accept.edge1 = accept;
          nfa2.accept.edge1 = accept;
          nfaStack.add(NFA(initial, accept));
        }
        break;
      case '+':
        {
          NFA nfa1 = nfaStack.removeLast();
          State initial = State();
          State accept = State();
          initial.edge1 = nfa1.initial;
          nfa1.accept.edge1 = nfa1.initial;
          nfa1.accept.edge2 = accept;
          nfaStack.add(NFA(initial, accept));
        }
        break;
      case '?':
        {
          NFA nfa1 = nfaStack.removeLast();
          State initial = State();
          State accept = State();
          initial.edge1 = nfa1.initial;
          initial.edge2 = accept;
          nfa1.accept.edge1 = accept;
          nfaStack.add(NFA(initial, accept));
        }
        break;
      default:
        {
          // Literal character
          State initial = State(ch);
          State accept = State();
          initial.edge1 = accept;
          nfaStack.add(NFA(initial, accept));
        }
        break;
    }
  }

  return nfaStack.last;
}

